-- Exportování struktury pro funkce tarkov_wiki.agregatedActivityPastYear
DELIMITER //
CREATE FUNCTION `agregatedActivityPastYear`(IN userID INT) RETURNS int(11)
BEGIN 
DECLARE output INT DEFAULT 0;
DECLARE comments int;
DECLARE changes int;

set comments = countComentsPastYear(userID);
SET changes = countChangesPastYear(userID)*5;
SET output = comments+changes;

RETURN output;
  
END//
DELIMITER ;

-- Exportování struktury pro procedura tarkov_wiki.approveChange
DELIMITER //
CREATE PROCEDURE `approveChange`(IN aproverID int,IN changeID INT)
BEGIN 

	if isMod(aproverID)=TRUE then
		UPDATE submited_change 
		SET user_id1=aproverID,approved=1 
		WHERE  submited_change.id = changeID;
	else
	 SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'aprover není mod nebo admin';
	END if;
	
	
END//
DELIMITER ;

-- Exportování struktury pro funkce tarkov_wiki.checkUser
DELIMITER //
CREATE FUNCTION `checkUser`(IN userName VARCHAR(30),IN paswd VARCHAR(64)) RETURNS tinyint(1)
BEGIN
DECLARE output boolean DEFAULT 0;  
DECLARE k INT DEFAULT 0; 

SELECT 
COUNT(tarkov_wiki.`user`.id) 
INTO k
from tarkov_wiki.`user`
WHERE tarkov_wiki.`user`.username=userName
AND tarkov_wiki.`user`.passwd=paswd;



 if k=1 then
		SET output = TRUE;
	else
	 SET output = FALSE;
	END if;

RETURN output;
  

END//
DELIMITER ;

