-- Exportování struktury pro funkce tarkov_wiki.countChangesPastYear
DELIMITER //
CREATE FUNCTION `countChangesPastYear`(IN userID INT) RETURNS int(11)
BEGIN 
DECLARE output INT DEFAULT 0;
DECLARE d DATETIME;
SET d = DATE_ADD(NOW(), INTERVAL -1 YEAR);

SELECT COUNT(tarkov_wiki.submited_change.id) INTO output
FROM tarkov_wiki.submited_change
WHERE tarkov_wiki.submited_change.user_id=userID AND tarkov_wiki.submited_change.changeTime>d AND tarkov_wiki.submited_change.approved=1 ; 

RETURN output;
  
END//
DELIMITER ;

-- Exportování struktury pro funkce tarkov_wiki.countComentsPastYear
DELIMITER //
CREATE FUNCTION `countComentsPastYear`(IN userID INT) RETURNS int(11)
BEGIN 
DECLARE output INT DEFAULT 0;
DECLARE d DATETIME;
SET d = DATE_ADD(NOW(), INTERVAL -1 YEAR);

SELECT COUNT(tarkov_wiki.`comment`.id) INTO output
FROM tarkov_wiki.`comment`
WHERE tarkov_wiki.`comment`.id=userID AND tarkov_wiki.`comment`.timest>d; 

RETURN output;
  
END//
DELIMITER ;

-- Exportování struktury pro procedura tarkov_wiki.createComment
DELIMITER //
CREATE PROCEDURE `createComment`(IN questID int,IN desctxt VARCHAR(3000),IN userName VARCHAR(45))
    DETERMINISTIC
BEGIN

DECLARE userID INT;
select tarkov_wiki.`user`.id into userID FROM  tarkov_wiki.`user` WHERE  tarkov_wiki.`user`.username=userName;
INSERT INTO `comment` (timest,`comment`.text,`comment`.user_id,`comment`.quest_id) VALUES (NOW(),desctxt,userID,questID);
	
	
END//
DELIMITER ;

-- Exportování struktury pro procedura tarkov_wiki.CreateMap
DELIMITER //
CREATE PROCEDURE `CreateMap`(IN mapnam VARCHAR(20),IN desctxt VARCHAR(3000))
    DETERMINISTIC
BEGIN

	INSERT INTO descr (descText) VALUES (desctxt);
	SET @_DescID= LAST_INSERT_ID();
	INSERT INTO maps (description_id,mapname) VALUES (@_DescID,mapnam);
 
	
END//
DELIMITER ;

-- Exportování struktury pro procedura tarkov_wiki.CreateQuest
DELIMITER //
CREATE PROCEDURE `CreateQuest`(
	IN `questName` VARCHAR(255),
	IN `desctxt` VARCHAR(3000),
	IN `xp` INT,
	IN `money` INT,
	IN `image` LONGBLOB,
	IN `questmap` int,
	IN `questtrader` int
)
    DETERMINISTIC
BEGIN
	
	DECLARE questId INT;
	INSERT INTO descr (descText) VALUES (desctxt);
	SET @_DescID= LAST_INSERT_ID();
	INSERT INTO quest (description_id,questName, xp_earned,money_earned,preview_image) VALUES (@_DescID,questName,xp,money,image);
 	SET questId = LAST_INSERT_ID();
 	INSERT INTO map_quest VALUES (questmap,questId);
 	INSERT INTO trader_quest VALUES (questtrader,questId);
	
END//
DELIMITER ;

-- Exportování struktury pro procedura tarkov_wiki.CreateTrader
DELIMITER //
CREATE PROCEDURE `CreateTrader`(IN trname VARCHAR(20),IN desctxt VARCHAR(3000))
    DETERMINISTIC
BEGIN

	INSERT INTO descr (descText) VALUES (desctxt);
	SET @_DescID= LAST_INSERT_ID();
	INSERT INTO trader (description_id,traderName) VALUES (@_DescID,trname);
 
	
END//
DELIMITER ;

-- Exportování struktury pro procedura tarkov_wiki.delEdit
DELIMITER //
CREATE PROCEDURE `delEdit`(IN editID INT)
    DETERMINISTIC
BEGIN
	
DELETE FROM tarkov_wiki.submited_change WHERE tarkov_wiki.submited_change.id=editID;
	
END//
DELIMITER ;

