-- Exportování struktury pro funkce tarkov_wiki.getHashByName
DELIMITER //
CREATE FUNCTION `getHashByName`(IN username VARCHAR(30)) RETURNS varchar(60) CHARSET utf8mb4 COLLATE utf8mb4_uca1400_ai_ci
BEGIN 
DECLARE output VARCHAR(60);

SELECT tarkov_wiki.`user`.passwd INTO output
FROM tarkov_wiki.`user`
WHERE tarkov_wiki.`user`.username=username; 

RETURN output;
  
END//
DELIMITER ;

-- Exportování struktury pro funkce tarkov_wiki.getIDByName
DELIMITER //
CREATE FUNCTION `getIDByName`(IN username VARCHAR(30)) RETURNS int(11)
BEGIN 
DECLARE output int;

SELECT tarkov_wiki.`user`.id INTO output
FROM tarkov_wiki.`user`
WHERE tarkov_wiki.`user`.username=username; 

RETURN output;
  
END//
DELIMITER ;

-- Exportování struktury pro funkce tarkov_wiki.isMod
DELIMITER //
CREATE FUNCTION `isMod`(IN userID INT) RETURNS tinyint(1)
BEGIN
  DECLARE userPer INT DEFAULT 1;  
    DECLARE output BOOLEAN DEFAULT FALSE;
    
SELECT roles_id INTO userPer
    FROM tarkov_wiki.`user`
    WHERE id = userID;
	
    IF userPer > 1 THEN
      SET output = TRUE;

   ELSE
      SET output = false;
   
  END IF;
  RETURN output;
  
END//
DELIMITER ;

