-- Exportování struktury pro funkce tarkov_wiki.jsonToMail
DELIMITER //
CREATE FUNCTION `jsonToMail`(IN jsonMail longtext) RETURNS varchar(256) CHARSET utf8mb4 COLLATE utf8mb4_uca1400_ai_ci
BEGIN 
DECLARE output longtext;
DECLARE s VARCHAR(256);
DECLARE s2 VARCHAR(256);
DECLARE s3 VARCHAR(256);
SET output = '';

   
   set @json='
[
  {"username":"testuser1", "domain":"google", "tld":"com"}
]';
   
SELECT * INTO s from json_table(jsonMail, '$[*]' 
  columns(
   name  varchar(10) PATH '$.username'
   )
) as jt;

SELECT * INTO s2 from json_table(jsonMail, '$[*]' 
  columns(
   name  varchar(10) PATH '$.domain'
   )
) as jt2;

SELECT * INTO s3 from json_table(jsonMail, '$[*]' 
  columns(
   name  varchar(10) PATH '$.tld'
   )
) as jt3;


	
 SELECT CONCAT(s,'@',s2,'.',s3) INTO output ;
  RETURN output;
  
END//
DELIMITER ;

