-- Exportování struktury pro procedura tarkov_wiki.newEdit
DELIMITER //
CREATE PROCEDURE `newEdit`(
	IN `questName` VARCHAR(255),
	IN `txt` VARCHAR(3000),
	IN `authorID` INT
)
    DETERMINISTIC
BEGIN
    DECLARE questId INT;
    SELECT questdescname.id INTO questId FROM questdescname WHERE questdescname.questname = questName;
    INSERT INTO tarkov_wiki.submited_change (description_id, user_id, descText, changeTime)
    VALUES (questId, authorID, txt, NOW());
END//
DELIMITER ;

-- Exportování struktury pro procedura tarkov_wiki.newUser
DELIMITER //
CREATE PROCEDURE `newUser`(IN usernm VARCHAR(40),IN pass VARCHAR(64),IN mail VARCHAR(255))
    DETERMINISTIC
pr:
BEGIN

if (usernameFree(usernm)=FALSE) then
SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'uživatelksé jméno je již zabrané';
leave pr;
ELSE 
	INSERT INTO user (username,passwd,roles_id,email) VALUES (usernm,pass,1,mail);
END if;


	
END//
DELIMITER ;

