-- Exportování struktury pro funkce tarkov_wiki.usernameFree
DELIMITER //
CREATE FUNCTION `usernameFree`(IN usrnm VARCHAR(30)) RETURNS tinyint(1)
BEGIN 
DECLARE output BOOLEAN DEFAULT FALSE;
DECLARE usernameTaken TINYINT DEFAULT 0;
SELECT EXISTS (SELECT * FROM tarkov_wiki.`user` WHERE tarkov_wiki.`user`.username=usrnm) INTO usernameTaken;
   

	
    IF usernameTaken= 1 THEN
      SET output = false;

   ELSE
      SET output = true;
   
  END IF;
  RETURN output;
  
END//
DELIMITER ;

-- Exportování struktury pro trigger tarkov_wiki.modApproval
SET @OLDTMP_SQL_MODE=@@SQL_MODE, SQL_MODE='STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION';
DELIMITER //
CREATE TRIGGER `modApproval` AFTER UPDATE ON `submited_change` FOR EACH ROW BEGIN
    DECLARE authorID1 INT;
    DECLARE modID1 INT;
    DECLARE questId INT;
    DECLARE oldDesID INT;
    DECLARE newDesID INT;
    DECLARE descrip VARCHAR(3000);

    IF NEW.approved = 1 AND isMod(NEW.user_id1) = TRUE THEN

        SET questId = NEW.description_id;
        SET descrip = NEW.descText;
        SET modID1 = NEW.user_id1;
        SET authorID1 = NEW.user_id;

        SELECT description_id INTO oldDesID
        FROM quest
        WHERE id = questId;

        INSERT INTO descr (descText) VALUES (descrip);
        SET newDesID = LAST_INSERT_ID();

        UPDATE quest SET description_id = newDesID
        WHERE id = questId;

        INSERT INTO edit_history (
            description_id,
            changeTime,
            authorID,
            modID
        ) VALUES (newDesID, NOW(), authorID1, modID1);

    END IF;
END//
DELIMITER ;
SET SQL_MODE=@OLDTMP_SQL_MODE;

-- Odebírání dočasné tabulky a vytváření struktury Pohledu
DROP TABLE IF EXISTS `coments`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `coments` AS select `user`.`username` AS `name`,`comment`.`timest` AS `timestamp`,`comment`.`text` AS `text`,`quest`.`questname` AS `quest` from ((`comment` join `user` on(`comment`.`user_id` = `user`.`id`)) join `quest` on(`quest`.`id` = `comment`.`quest_id`))
;

-- Odebírání dočasné tabulky a vytváření struktury Pohledu
DROP TABLE IF EXISTS `questdescname`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `questdescname` AS select `quest`.`questname` AS `questname`,`descr`.`id` AS `id` from (`quest` join `descr` on(`quest`.`id` = `descr`.`id`))
;

-- Odebírání dočasné tabulky a vytváření struktury Pohledu
DROP TABLE IF EXISTS `questnametext`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `questnametext` AS select `quest`.`questname` AS `name`,`descr`.`descText` AS `txt` from (`quest` join `descr` on(`quest`.`description_id` = `descr`.`id`))
;

-- Odebírání dočasné tabulky a vytváření struktury Pohledu
DROP TABLE IF EXISTS `questselect`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `questselect` AS select `quest`.`questname` AS `name`,`descr`.`descText` AS `popis`,`quest`.`xp_earned` AS `xp`,`quest`.`money_earned` AS `moni`,`maps`.`mapname` AS `mapa`,`trader`.`traderName` AS `trader`,`quest`.`id` AS `idq`,`quest`.`preview_image` AS `img` from (((((`quest` join `descr` on(`quest`.`description_id` = `descr`.`id`)) join `trader_quest` on(`quest`.`id` = `trader_quest`.`quest_id`)) join `trader` on(`trader`.`id` = `trader_quest`.`trader_id`)) join `map_quest` on(`map_quest`.`quest_id` = `quest`.`id`)) join `maps` on(`maps`.`id` = `map_quest`.`maps_id`))
;

-- Odebírání dočasné tabulky a vytváření struktury Pohledu
DROP TABLE IF EXISTS `questyjmena`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `questyjmena` AS select `quest`.`questname` AS `name`,`trader`.`traderName` AS `trader`,`maps`.`mapname` AS `mapa` from (((((`quest` join `descr` on(`quest`.`description_id` = `descr`.`id`)) join `trader_quest` on(`quest`.`id` = `trader_quest`.`quest_id`)) join `trader` on(`trader`.`id` = `trader_quest`.`trader_id`)) join `map_quest` on(`map_quest`.`quest_id` = `quest`.`id`)) join `maps` on(`maps`.`id` = `map_quest`.`maps_id`))
;

-- Odebírání dočasné tabulky a vytváření struktury Pohledu
DROP TABLE IF EXISTS `unapprovedchanges`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `unapprovedchanges` AS select `submited_change`.`descText` AS `NewTxt`,`descr`.`descText` AS `OldTxt`,`user`.`username` AS `usrnm`,`submited_change`.`changeTime` AS `timest`,`submited_change`.`id` AS `id` from ((`submited_change` join `user` on(`user`.`id` = `submited_change`.`user_id`)) join `descr` on(`submited_change`.`description_id` = `descr`.`id`)) where `submited_change`.`approved` <> 1 order by `submited_change`.`changeTime` desc
;

-- Odebírání dočasné tabulky a vytváření struktury Pohledu
DROP TABLE IF EXISTS `useractivity`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `useractivity` AS select `user`.`id` AS `ID uživatele`,`user`.`username` AS `uživatelské jméno`,`jsonToMail`(`user`.`email`) AS `email`,`agregatedActivityPastYear`(`user`.`id`) AS `aktivita za poslední rok` from `user`
;

